SELECT set_config('request.jwt.claim.role','service_role',false);
SELECT set_config('request.jwt.claim.sub','f49d6153-1835-4455-81f3-2918d5d3484e',false);
BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A factory bids on an order requiring 45,000 pieces delivered in 28 days. The style has a SAM of 22 minutes. The factory has 3 lines available, each capable of running at 75% efficiency with 45 operators per line, 10 working hours/day (600 minutes). Can the factory meet this deadline using all 3 lines, and if not, by how many pieces will it fall short?', '["Daily capacity per line = (45 operators × 600 min × 0.75)/22 min = 20,250/22 ≈ 920.5 pieces/day/line. 3 lines = 2,761.4 pieces/day. Over 28 days = 77,318 pieces — EASILY meets the 45,000 target with substantial spare capacity","Daily capacity per line ≈ 920.5 pieces; 3 lines over 28 days ≈ 77,318 pieces, meeting the target — but the distractor calculation of directly multiplying 45×600×0.75×3×28÷22 without correctly structuring the per-line-per-day calculation first would also arrive near this figure only by coincidence, so the STRUCTURED calculation (per line, per day, then scaled) is the reliable method, not a shortcut","The factory falls short by exactly 12,000 pieces, incorrectly using only 2 lines'' worth of capacity in the calculation","The factory falls short by exactly 5,000 pieces, incorrectly using 20 working days instead of the full 28 days stated"]'::jsonb, 'Daily capacity per line = (45 operators × 600 min × 0.75)/22 min = 20,250/22 ≈ 920.5 pieces/day/line. 3 lines = 2,761.4 pieces/day. Over 28 days = 77,318 pieces — EASILY meets the 45,000 target with substantial spare capacity', 'Per-line daily earned minutes = 45 operators × 600 minutes × 0.75 efficiency = 20,250 earned minutes/day. Daily output per line = 20,250 ÷ 22 (SAM) ≈ 920.5 pieces. Three lines: 920.5 × 3 ≈ 2,761.4 pieces/day. Over 28 days: 2,761.4 × 28 ≈ 77,318 pieces — this comfortably exceeds the 45,000-piece target, meaning the factory could actually meet this order using FEWER than all 3 lines or in fewer than 28 days, information useful for capacity planning and potentially bidding on additional concurrent orders.', 3, '{"capacity-feasibility-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A merchandiser''s landed cost model for an FOB $8.40/piece garment includes ocean freight ($0.35/piece), marine insurance (0.3% of FOB+freight value), import duty (12% of FOB+freight+insurance, i.e., the customs value), and inland trucking ($0.18/piece). What is the total landed cost per piece?', '["FOB+freight = $8.75. Insurance = 0.003×$8.75=$0.02625. Customs value = $8.75+$0.02625=$8.77625. Duty = 0.12×$8.77625=$1.0532. Total landed = $8.77625+$1.0532+$0.18 ≈ $10.01","Total landed cost = $8.40+$0.35+$0.18 = $8.93, incorrectly omitting both insurance and duty from the calculation entirely","Total landed cost = $8.40×1.12 = $9.41, incorrectly applying duty only to the base FOB price rather than to the full customs value (FOB+freight+insurance)","Total landed cost = $8.40+$1.0532 = $9.45, incorrectly omitting freight, insurance, and trucking from the final total despite including them conceptually in the duty base"]'::jsonb, 'FOB+freight = $8.75. Insurance = 0.003×$8.75=$0.02625. Customs value = $8.75+$0.02625=$8.77625. Duty = 0.12×$8.77625=$1.0532. Total landed = $8.77625+$1.0532+$0.18 ≈ $10.01', 'This requires correctly SEQUENCING multiple cost layers, since duty is calculated on the CUSTOMS VALUE (FOB+freight+insurance), not on FOB alone: Step 1: FOB+freight = $8.40+$0.35=$8.75. Step 2: Insurance = 0.3% of $8.75 = $0.02625. Step 3: Customs value = $8.75+$0.02625=$8.77625. Step 4: Duty = 12% of $8.77625≈$1.0532. Step 5: Total landed cost = customs value + duty + trucking = $8.77625+$1.0532+$0.18≈$10.01 — this connects directly to the earlier landed-cost/FOB-margin-planning discussion, illustrating the real multi-step calculation a merchandiser must perform (not just adding a flat percentage to FOB) to accurately determine achievable margin.', 3, '{"landed-cost-multi-step-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'advanced', 'multiple_choice', 'A factory''s quality department tracks ''cost of poor quality'' (COPQ) as a percentage of total production cost. This quarter, COPQ breaks down as: rework labor 1.8%, scrapped material 0.9%, and customer returns/chargebacks 2.4%. If total quarterly production cost is $2,400,000, what is the TOTAL dollar amount of COPQ, and which single component should the quality team prioritize investigating first based on this breakdown?', '["Total COPQ = (1.8%+0.9%+2.4%) × $2,400,000 = 5.1% × $2,400,000 = $122,400. Customer returns/chargebacks (2.4%, the largest component) should be prioritized first, since it represents both the largest cost AND connects to the earlier Cost-of-Quality principle that EXTERNAL failure costs (reaching the customer) are the most expensive and most urgent category to address","Total COPQ = $2,400,000 × 5.1% = $122,400, but scrapped material should be prioritized first simply because it has the smallest percentage and would therefore be the easiest and fastest to fully eliminate","Total COPQ should be calculated by ADDING the three percentages directly to the total cost as dollar amounts rather than as percentages, giving a total of $2,400,005.1, an obviously incorrect order of magnitude","COPQ percentage breakdown has no relationship to which category should be prioritized for improvement investment, making this entire prioritization question technically unanswerable from the given data"]'::jsonb, 'Total COPQ = (1.8%+0.9%+2.4%) × $2,400,000 = 5.1% × $2,400,000 = $122,400. Customer returns/chargebacks (2.4%, the largest component) should be prioritized first, since it represents both the largest cost AND connects to the earlier Cost-of-Quality principle that EXTERNAL failure costs (reaching the customer) are the most expensive and most urgent category to address', 'Total COPQ = 5.1% × $2,400,000 = $122,400. Beyond the calculation itself, this connects directly to the earlier Cost-of-Quality escalation principle (prevention < appraisal < internal failure < external failure, in ascending cost/urgency) — customer returns/chargebacks represent EXTERNAL failure cost (the most expensive, most reputation-damaging category, since defects reached the customer), and it''s ALSO the largest dollar component here ($57,600 of the $122,400 total) — both the magnitude AND the category-severity principle point toward prioritizing investigation into what''s driving customer returns/chargebacks first, rather than the smaller-magnitude, less severe-category rework or scrap costs.', 3, '{"COPQ-calculation-prioritization"}'::text[]);
COMMIT;
